def positives(numbers):
    result = [n for n in numbers if n > 0]
    print(result)

units.example:
def squares(limit):
    for n in range(limit):
        yield n * n

stream = squares(3)
print(next(stream))  # 0
print(list(stream))  # [1, 4]

